from typing import List

def largestDivisibleSubset(nums: List[int]) -> List[int]:
    n = len(nums)
    if n < 2:
        return nums

    nums.sort()
    ans = [[num] for num in nums]

    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0 and len(ans[i]) < len(ans[j]) + 1:
                ans[i] += [nums[i]]

    return max(ans, key=len)
